// Shared by migrate.mjs (Stencil v5) and build.mjs (Stencil 4 reference): copy upstream's core/ into a
// working folder, leaving out what the build does not need (tests, stories, docker, lint config).
import { cpSync, mkdirSync, rmSync } from 'node:fs';
import { basename, join } from 'node:path';
import { root } from './paths.mjs';

// components.d.ts is generated by Stencil; upstream's is v4-shaped (it imports @stencil/core/internal) and must not seed the v5 build
const SKIP_FILES = [/^components\.d\.ts$/, /\.spec\.tsx?$/, /\.e2e\.ts$/, /\.stories\.tsx?$/, /^jest\.d\.ts$/];
const SKIP_DIRS = new Set(['node_modules', 'test', 'e2e', '.tmp', 'dist', 'components-out']);
const KEEP = ['src', 'tsconfig.json', 'tsconfig.base.json', 'package.json', 'LICENSE'];

export function copyCore(dest) {
  const from = join(root, 'upstream', 'core');
  rmSync(dest, { recursive: true, force: true });
  mkdirSync(dest, { recursive: true });
  let files = 0;
  for (const entry of KEEP) {
    cpSync(join(from, entry), join(dest, entry), {
      recursive: true,
      filter: (src) => {
        const name = basename(src);
        if (SKIP_DIRS.has(name) && src !== from) return false;
        if (SKIP_FILES.some((re) => re.test(name))) return false;
        files++;
        return true;
      },
    });
  }
  return files;
}
